    days, remainder = divmod(minutes, 1440)
    hours, mins = divmod(remainder, 60)
    return \"\".join(f\"{Decimal(amount)}{unit}\"
                   for amount, unit in ((days, \"d\"), (hours, \"h\"), (mins, \"m\")) if amount)


