        return dt.date.fromisoformat(word)


def _time(word):
    if not re.fullmatch(TIME, word):
        raise ValueError(\"invalid time\")
    return dt.time.fromisoformat(word)


def _month_day(word):
    if word == \"last\":
        return word
    if re.fullmatch(r\"[1-9]|[12][0-9]|3[01]\", word):
        return int(word)
    raise ValueError(\"invalid month day\")


